import React, {useCallback, useState} from 'react';
import type {Ref} from 'react';

import {Suggest, SuggestView} from '~/src/components/Suggest';
import type {SuggestProps} from '~/src/components/Suggest';
import {useConditionallyControlledState} from '~/src/hooks/useConditionallyControlledState';

type SuggestPropsToOmit =
    | 'text'
    | 'onTextUpdate'
    | 'applicableInputValue'
    | 'onInputEnterKeyDown'
    | 'onUpdate';

export type EntitiesSuggestProps<EntityType extends unknown = {}> = Omit<
    SuggestProps<EntityType>,
    SuggestPropsToOmit
> & {
    onChange?: (entity: EntityType | null) => void;
    getItemId: (item: EntityType) => string | number;
    getSuggestTextFromClickedItem: (item: EntityType) => string;
    suggestRef?: Ref<SuggestView<EntityType>>;
    text?: string;
    onTextChange?: (text: string) => void;
};

export const EntitiesSuggest = <EntityType extends unknown = {}>({
    onItemClick,
    onChange,
    hasClear = true,
    debounce = 500,
    getItems,
    getItemId,
    getSuggestTextFromClickedItem,
    suggestRef,
    text: providedText = '',
    onTextChange,
    getItemsOnMount,
    ...suggestProps
}: EntitiesSuggestProps<EntityType>) => {
    const [text, setText] = useConditionallyControlledState(providedText, onTextChange);
    const [currentEntity, setCurrentEntity] = useState<EntityType | null>(null);

    const handleItemClick = useCallback(
        (item: EntityType, index?: number, fromKeyboard?: boolean) => {
            setText(getSuggestTextFromClickedItem(item));

            if (!currentEntity || getItemId(item) !== getItemId(currentEntity)) {
                setCurrentEntity(item);
                onChange?.(item);
            }

            return onItemClick?.(item, index, fromKeyboard);
        },
        [currentEntity, getSuggestTextFromClickedItem, getItemId, onChange, onItemClick, setText],
    );

    const handleUpdate = useCallback(
        (input: string) => {
            setText(input);

            if (currentEntity !== null) {
                setCurrentEntity(null);
                onChange?.(null);
            }
        },
        [currentEntity, onChange, setText],
    );

    return (
        <Suggest<EntityType>
            {...suggestProps}
            ref={suggestRef}
            text={text}
            onUpdate={handleUpdate}
            getItems={getItems}
            onItemClick={handleItemClick}
            debounce={debounce}
            hasClear={hasClear}
            syncPopupOnResize
            getItemsOnMount={getItemsOnMount || providedText.length > 0}
            autoComplete={false}
        />
    );
};
